import React, { useEffect, useState } from "react";

const Agreement = () => {
  const [accepted, setAccepted] = useState(false);

  // Load existing agreement data
  useEffect(() => {
    fetch("http://localhost:5000/userProfile")
      .then((response) => response.json())
      .then((data) => {
        if (data.agreement) {
          setAccepted(data.agreement.accepted);
        }
      })
      .catch((error) => console.log(error));
  }, []);

  const handleSubmit = () => {
    if (!accepted) {
      alert("Please accept the agreement");
      return;
    }

    fetch("http://localhost:5000/userProfile", {
      method: "PATCH",
      headers: {
        "Content-Type": "application/json"
      },
      body: JSON.stringify({
        agreement: {
          accepted: true
        }
      })
    })
      .then((response) => response.json())
      .then(() => {
        alert("Agreement submitted successfully");
      })
      .catch((error) => {
        console.log(error);
        alert("Error saving agreement");
      });
  };

  return (
    <div className="form-card">
      <div className="form-header">
        <h2>Agreement</h2>
        <p>Please review and accept the agreement</p>
      </div>

      <div className="agreement-box">
        <p>
          I agree to the terms and conditions applicable to the
          vendor profile and services.
        </p>

        <p>
          I confirm that the information provided by me is accurate
          and complete.
        </p>
      </div>

      <div className="agreement-check">
        <input
          type="checkbox"
          checked={accepted}
          onChange={(e) => setAccepted(e.target.checked)}
        />

        <label>
          I agree to the terms and conditions
        </label>
      </div>

      <div className="form-footer">
        <button
          className="save-button"
          onClick={handleSubmit}
        >
          Submit Agreement
        </button>
      </div>
    </div>
  );
};

export default Agreement;
